import re, math
from playwright.sync_api import sync_playwright
Dw=open("../dist/svg/mark-tight_white.svg").read(); D=re.search(r' d="([^"]+)"',Dw)[1]
MW,MH=[int(x) for x in re.search(r'viewBox="0 0 (\d+) (\d+)"',Dw).groups()]
B="#1A73E8";INK="#0f172a";SL="#475569"
def mark(w,c=B): return f'<svg viewBox="0 0 {MW} {MH}" width="{w}" height="{w*MH/MW:.1f}"><path fill="{c}" d="{D}"/></svg>'
def ic(p,c=B,s=30,w=1.8): return f'<svg width="{s}" height="{s}" viewBox="0 0 24 24" fill="none" stroke="{c}" stroke-width="{w}" stroke-linecap="round" stroke-linejoin="round">{p}</svg>'
PIN='<path d="M12 21s-6.5-5.6-6.5-11a6.5 6.5 0 0 1 13 0c0 5.4-6.5 11-6.5 11z"/><circle cx="12" cy="10" r="2.4"/>'
CPU='<rect x="6" y="6" width="12" height="12" rx="2.5"/><rect x="9.5" y="9.5" width="5" height="5" rx="1"/><path d="M9 2.5v3M15 2.5v3M9 18.5v3M15 18.5v3M2.5 9h3M2.5 15h3M18.5 9h3M18.5 15h3"/>'
SHIELD='<path d="M12 3l7.5 3v5.5c0 4.6-3.1 8.2-7.5 9.5-4.4-1.3-7.5-4.9-7.5-9.5V6z"/><path d="M8.6 12.2l2.5 2.5 4.4-4.9"/>'
WALLET='<rect x="3" y="6" width="18" height="13" rx="3"/><path d="M3 10h18M16 14.5h2"/>'
cx,cy=540,650
pills=[(197,535,"USA","North America"),(883,535,"Germany","Europe"),(197,650,"Canada","North America"),(883,650,"France","Europe"),(197,765,"Australia","Oceania"),(883,765,"Singapore","Asia-Pacific")]
lines="".join(f'<path d="M{cx} {cy} Q{(cx+x)/2} {(cy+y)/2+(-26 if y<cy else 26 if y>cy else 0)} {x} {y}" fill="none" stroke="{B}" stroke-opacity=".35" stroke-width="2" stroke-dasharray="2 9" stroke-linecap="round"/><circle cx="{(cx+x*1.0)/2+(x-cx)*.18:.0f}" cy="{(cy+y)/2+(y-cy)*.12:.0f}" r="4.5" fill="{B}" opacity=".7"/>' for x,y,*_ in pills)
rings="".join(f'<circle cx="{cx}" cy="{cy}" r="{r}" fill="none" stroke="{B}" stroke-opacity="{o}" stroke-width="1.6" {d}/>' for r,o,d in [(335,.10,'stroke-dasharray="3 10"'),(250,.14,''),(160,.18,'stroke-dasharray="2 8"')])
globe=f'<g fill="none" stroke="{B}" stroke-opacity=".09" stroke-width="1.4"><circle cx="{cx}" cy="{cy}" r="335"/>'+"".join(f'<ellipse cx="{cx}" cy="{cy}" rx="{335*k}" ry="335"/>' for k in (.3,.62,.88))+"".join(f'<ellipse cx="{cx}" cy="{cy+335*l}" rx="{335*math.sqrt(1-l*l)}" ry="{335*math.sqrt(1-l*l)*.14}"/>' for l in (-.6,-.3,0,.3,.6))+'</g>'
def pill(x,y,t,s):
    return f'<div style="position:absolute;left:{x}px;top:{y}px;transform:translate(-50%,-50%);display:flex;align-items:center;gap:13px;width:274px;background:rgba(255,255,255,.78);backdrop-filter:blur(10px);border:1.5px solid rgba(255,255,255,.95);border-radius:22px;padding:11px 24px 11px 12px;box-shadow:0 24px 44px -16px rgba(26,115,232,.35),0 4px 12px rgba(15,23,42,.06),inset 0 1px 0 #fff"><span style="width:46px;height:46px;border-radius:15px;background:linear-gradient(150deg,#4a9bff,{B});display:flex;align-items:center;justify-content:center;box-shadow:0 8px 16px rgba(26,115,232,.35)">{ic(PIN,"#fff",24,2)}</span><span style="white-space:nowrap;flex:1"><b style="display:block;font-size:24px;font-weight:800;letter-spacing:-.6px;color:{INK}">{t}</b><i style="font-style:normal;font-size:14px;color:{SL};font-weight:600">{s}</i></span><span style="width:9px;height:9px;border-radius:50%;background:#16c47f;box-shadow:0 0 0 4px rgba(22,196,127,.18);margin-left:4px"></span></div>'
def blade(y,o):
    return f'<div style="position:absolute;left:0;top:{y}px;width:210px;height:62px;border-radius:20px;background:linear-gradient(160deg,#5aa6ff,{B} 60%,#0d57c4);box-shadow:0 18px 30px -10px rgba(13,87,196,.55),inset 0 1.5px 0 rgba(255,255,255,.55);opacity:{o}"><div style="position:absolute;left:22px;top:24px;display:flex;gap:7px"><i style="width:9px;height:9px;border-radius:50%;background:#bdf5dc;box-shadow:0 0 8px #7ff0bd"></i><i style="width:9px;height:9px;border-radius:50%;background:rgba(255,255,255,.55)"></i></div><div style="position:absolute;right:22px;top:20px;width:92px;height:22px;border-radius:8px;background:rgba(255,255,255,.22);display:flex;align-items:center;gap:6px;padding:0 8px"><i style="flex:1;height:3px;border-radius:2px;background:rgba(255,255,255,.7)"></i><i style="flex:1;height:3px;border-radius:2px;background:rgba(255,255,255,.7)"></i><i style="flex:1;height:3px;border-radius:2px;background:rgba(255,255,255,.7)"></i></div></div>'
def feat(icon,t,s):
    return f'<div style="flex:1;display:flex;align-items:center;gap:14px;background:rgba(255,255,255,.85);border:1.5px solid #e4edfb;border-radius:22px;padding:16px 18px;box-shadow:0 14px 30px -14px rgba(26,115,232,.28),0 2px 6px rgba(15,23,42,.04)"><span style="width:46px;height:46px;border-radius:14px;background:#eaf2ff;display:flex;align-items:center;justify-content:center;flex:none">{ic(icon,B,26,1.9)}</span><span><b style="display:block;font-size:17px;font-weight:800;letter-spacing:-.3px;color:{INK};white-space:nowrap">{t}</b><i style="font-style:normal;font-size:14px;color:{SL};font-weight:600">{s}</i></span></div>'
html=f"""<html><style>*{{margin:0;box-sizing:border-box}}body{{font-family:'Inter Display','Inter',Arial,sans-serif;width:1080px;height:1080px;position:relative;overflow:hidden;background:#fff;color:{INK}}}</style><body>
<div style="position:absolute;inset:0;background:radial-gradient(60% 45% at 50% 60%,rgba(26,115,232,.20) 0%,rgba(26,115,232,0) 70%),radial-gradient(50% 35% at 100% 0%,rgba(120,175,255,.35) 0%,rgba(120,175,255,0) 70%),linear-gradient(180deg,#f7faff 0%,#eef4ff 100%)"></div>
<svg width="1080" height="1080" style="position:absolute;inset:0"><defs><radialGradient id="g"><stop offset="0" stop-color="{B}" stop-opacity=".45"/><stop offset="1" stop-color="{B}" stop-opacity="0"/></radialGradient><filter id="bl" x="-50%" y="-300%" width="200%" height="700%"><feGaussianBlur stdDeviation="16"/></filter></defs>{globe}{rings}<circle cx="{cx}" cy="{cy}" r="170" fill="url(#g)"/>{lines}<ellipse cx="{cx}" cy="{cy+112}" rx="104" ry="14" fill="#0d57c4" opacity=".4" filter="url(#bl)"/></svg>
<div style="position:absolute;left:0;right:0;top:40px;display:flex;justify-content:center;align-items:center;gap:14px">{mark(60)}<span style="font-size:32px;font-weight:700;letter-spacing:-1px">SatisfyCloud</span></div>
<div style="position:absolute;left:0;right:0;top:118px;text-align:center"><span style="display:inline-flex;align-items:center;gap:10px;background:#fff;color:{B};font-weight:800;font-size:17px;letter-spacing:1.4px;border-radius:999px;padding:9px 22px;box-shadow:0 8px 22px rgba(26,115,232,.18),0 0 0 1.5px #dbe8ff"><i style="width:8px;height:8px;border-radius:50%;background:#16c47f;display:block"></i>GLOBAL NVMe VPS NETWORK</span></div>
<div style="position:absolute;left:0;right:0;top:172px;text-align:center"><div style="font-size:70px;line-height:1.02;font-weight:800;letter-spacing:-3px;color:{INK}">Unmatched Power.<br><span style="color:{B}">Zero Boundaries.</span></div>
<div style="font-size:24px;line-height:1.4;color:{SL};font-weight:500;margin:18px auto 0;max-width:760px">Deploy high-frequency cloud VPS across 6 global hubs<br>in under 60 seconds.</div></div>
<div style="position:absolute;left:{cx-105}px;top:{cy-100}px;width:210px;height:230px"><div style="position:relative;width:210px;height:230px">{blade(0,1)}{blade(78,1)}{blade(156,1)}</div></div>
{"".join(pill(*p) for p in pills)}
<div style="position:absolute;left:46px;right:46px;top:845px;display:flex;gap:16px">{feat(CPU,"Dedicated vCPU &amp; NVMe","Pure raw speed")}{feat(SHIELD,"Full Root &amp; DDoS Shield","Enterprise control")}{feat(WALLET,"Crypto, Cards &amp; Local Pay","Instant activation")}</div>
<div style="position:absolute;left:0;right:0;bottom:32px;display:flex;justify-content:center"><span style="display:inline-flex;align-items:center;gap:16px;background:linear-gradient(180deg,#3b8bf0,{B});color:#fff;font-size:26px;font-weight:700;border-radius:999px;padding:17px 40px;box-shadow:0 18px 36px -8px rgba(26,115,232,.55),inset 0 1px 0 rgba(255,255,255,.4)">Deploy Your VPS →<span style="opacity:.55">|</span><span style="font-weight:800">satisfycloud.com</span></span></div>
</body></html>"""
open("vps.html","w").write(html)
