    pg=br.new_page(viewport={"width":1080,"height":1080},device_scale_factor=2);pg.goto("file:///home/user/logo-design-skill/satisfycloud/social/vps.html");pg.wait_for_timeout(200);pg.screenshot(path="facebook-vps-network-post@2x.png");br.close()
